"""Whole native hardware-cap setup/DX adjustment -> state10 contract."""
from pathlib import Path
from datetime import datetime,timezone
import itertools,json,re,struct,subprocess,tempfile
from verify_source_anisotropy import ROOT,OUT,VS,SHADER,MATERIAL,sha,need,put,effective
from verify_ifm_draw_packet import check_ranges

def main():
    run=Path(tempfile.mkdtemp(prefix='capabilities-',dir=OUT));print('Capability directory: '+str(run),flush=True)
    idx=json.loads((OUT/'latest-verification.json').read_text());need(sha(idx['receipt'])==idx['receipt_sha256'],'state10 native evidence');prior=json.loads(Path(idx['receipt']).read_text());sources=dict(prior['source_sha256']);protected=dict(prior['protected_sha256']);protected[idx['receipt']]=idx['receipt_sha256']
    for group in [sources,protected]:need(all(sha(p)==h for p,h in group.items()),'preceding current identities')
    audit=json.loads((OUT/'native-capability-audit.local.json').read_text());need(sha(SHADER)==audit['sha256'],'same original module');check_ranges(SHADER,'shaderapidx9-disassembly.txt',[(r['name'],int(r['start'],16),int(r['end_exclusive'],16)) for r in audit['ranges']]);protected[str(OUT/'native-capability-audit.local.json')]=sha(OUT/'native-capability-audit.local.json')
    for name in ['probe_source_anisotropy_caps_x86.cpp',Path(__file__).name]:sources[str(ROOT/'work'/name)]=sha(ROOT/'work'/name)
    rows=[[maximum,support,request,override,convar,stages,0] for maximum,support,request,override,convar,stages in itertools.product([0,1,2,4,8,16,32,64,0xffffffff],range(4),[90,92,95,100],[90,92,95,100],range(2),[0,1,16])];query=run/'caps-input.bin';query.write_bytes(struct.pack('<I',len(rows))+b''.join(struct.pack('<7I',*q) for q in rows));put(run/'queries.json',rows)
    build=run/'build.cmd';build.write_text('\n'.join(['@echo off',f'cd /d "{ROOT}"',f'call "{VS.parent/"vcvars32.bat"}" >nul','if errorlevel 1 exit /b 1',f'cl /nologo /std:c++17 /fp:strict /EHsc /W4 /O2 work\\probe_source_anisotropy_caps_x86.cpp /Fo:"{run/"caps.obj"}" /Fe:"{run/"caps.exe"}" >"{run/"build.log"}" 2>&1','if errorlevel 1 exit /b 1','exit /b 0','']))
    def execute(args,label,ok=True):
        p=subprocess.run(list(map(str,args)),cwd=ROOT,capture_output=True,text=True,timeout=300,creationflags=subprocess.CREATE_NO_WINDOW);(run/(label+'.log')).write_text(p.stdout+p.stderr)
        if ok:need(p.returncode==0,label+' failed: '+(p.stdout+p.stderr)[-1800:])
        return p
    execute(['cmd.exe','/d','/c',build],'build-driver');exe=run/'caps.exe';b=exe.read_bytes();pe=struct.unpack_from('<I',b,60)[0];need(struct.unpack_from('<H',b,pe+4)[0]==0x14c and struct.unpack_from('<H',b,pe+24)[0]==0x10b,'private x86 only');warnings=re.findall(r'warning (C\d+): ([^\r\n]+)',(run/'build.log').read_text());need(not warnings,'warning-free caps oracle')
    aniso=prior['executables']['aniso'];need(sha(aniso['path'])==aniso['sha256'],'actual tested state10 executable');traces={};stats=[]
    for repeat in range(2):
        trace=run/f'caps-{repeat}.bin';execute([exe,SHADER,query,trace],f'caps-{repeat}');data=trace.read_bytes();need(struct.unpack_from('<I',data)[0]==len(rows),'caps trace count');at=4;child=[];dx_counts={};valid_aniso=0
        for serial,q in enumerate(rows):
            h=struct.unpack_from('<14I',data,at);at+=56;current=data[at:at+0x2d8];at+=0x2d8;need(h[:8]==(serial,*q),'caps row identity');maximum=q[0] if q[1]&1 else 1;need(h[8:10]==(maximum,q[5]) and h[10]&0x30==q[1]<<4 and h[11:]==(q[3],1,1),'actual hardware getter/stage/aniso flags and maxdxlevel results');need(struct.unpack_from('<I',current,0x234)[0]==maximum and struct.unpack_from('<I',current,0x22c)[0]==q[5],'current caps raw fields');need(current[0x2cc]&0x30==(q[1]<<4),'min/mag capability bits survive DX adjustment');dx_counts[q[3]]=dx_counts.get(q[3],0)+1;valid_aniso+=int(1<maximum<0x80000000);child.append([1,maximum,q[5],serial%2,0,0])
        need(at==len(data),'complete current-caps framing');traces[str(trace)]=sha(trace)
        child_query=run/f'aniso-input-{repeat}.bin';child_query.write_bytes(struct.pack('<I',len(child))+b''.join(struct.pack('<6I',*q) for q in child));pub=run/f'publication-{repeat}.bin';applied=run/f'aniso-{repeat}.bin';execute([aniso['path'],'material',MATERIAL,child_query,pub],f'publication-{repeat}');execute([aniso['path'],'shader',SHADER,pub,applied],f'aniso-{repeat}');data=applied.read_bytes();need(struct.unpack_from('<I',data)[0]==len(child),'observed capabilities to state10 count');at=4;events=0
        for serial,q in enumerate(child):
            h=struct.unpack_from('<12I',data,at);at+=48;n=h[-1];actual=[struct.unpack_from('<3I',data,at+12*k) for k in range(n)];at+=12*n;count=struct.unpack_from('<I',data,at)[0];at+=4;cache=struct.unpack_from('<'+'I'*count,data,at);at+=count*4;value=effective(q[0],q[1]);need(h[:11]==(serial,*q,1,q[1],1,q[2]),'state10 observed hardware inputs');need(count==q[2] and actual==[(stage,10,value) for stage in range(q[2])] and cache==(value,)*count,'actual driver-limit submissions from propagated caps');events+=n
        need(at==len(data),'complete dependent native trace');traces[str(applied)]=sha(applied);traces[str(pub)]=sha(pub);stats.append({'cases':len(rows),'dxlevel_cases':dx_counts,'positive_supported_aniso_cases':valid_aniso,'state10_events':events});print('PASS capability propagation repeat '+str(repeat)+' '+json.dumps(stats[-1]),flush=True)
    need(stats[0]==stats[1],'exact repeated stats')
    for name in ['caps','publication','aniso']:need((run/(name+'-0.bin')).read_bytes()==(run/(name+'-1.bin')).read_bytes(),'exact native repeats '+name)
    old=sha(query);p=execute([exe,SHADER,query,query],'existing-output',False);need(p.returncode!=0 and sha(query)==old,'existing output preserved')
    for group in [sources,protected]:need(all(sha(p)==h for p,h in group.items()),'final identities')
    result={'status':'VERIFIED whole native capability wrapper/setup/DX adjustment and downstream state10 with controlled source caps; D3D9 raw producer static only and x64 anisotropic GPU integration pending','time_utc':datetime.now(timezone.utc).isoformat(),'previous_goal_turn':'PROGRESS','cases':len(rows),'repetitions':2,'stats':stats,'executable':{'path':str(exe),'sha256':sha(exe),'compiler_warnings':warnings},'dependent_state10_executable':aniso,'native_state10_verification':idx,'source_sha256':sources,'protected_sha256':protected,'trace_sha256':traces,'limits':['Actual original driver-cap producer GetDeviceCaps and decode blocks statically authenticated, not executed. Windows headers assert TextureFilterCaps offset0x40, MaxAnisotropy0x6c and actual min/mag capability masks. Raw fixture uses derived Source max=driver max if MINANISO else1, raw min/mag bits4/5.','Whole original capability wrapper100038d0, setup10003830, adjustment10003730 execute. Command-line -maxdxlevel query and ConVar parent are controlled host services. Default/original caps copies, source objects and outer guards preserved. Actual native getter reads adjusted current caps; supported min/mag bits/max survive tested levels90/92/95/100.','Raw maximum0xffffffff and other unusual values are synthetic branch controls, not accepted real GPU caps. No real original driver/device initialization, original process or anisotropic pixels; state10 COM submissions remain controlled observations.','Production editor sources/builds unchanged. Existing native-x64 editor has not gained anisotropic filtering from this research.']}
    receipt=run/'results.json';put(receipt,result);put(OUT/'latest-caps-verification.json',{'receipt':str(receipt),'receipt_sha256':sha(receipt)});print(json.dumps({k:result[k] for k in ['status','cases','repetitions','stats']},indent=2),flush=True)
if __name__=='__main__':main()
